<?php
session_start(); require_once __DIR__.'/config/database.php';
if(empty($_SESSION['cart'])){header('Location: cart.php');exit;}
$ids=array_map('intval',array_keys($_SESSION['cart']));$marks=implode(',',array_fill(0,count($ids),'?'));$stmt=$pdo->prepare("SELECT * FROM products WHERE id IN ($marks)");$stmt->execute($ids);$total=0;foreach($stmt->fetchAll() as $p)$total+=$p['price']*$_SESSION['cart'][$p['id']];
$done=false;$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$address=trim($_POST['address']??'');if(!$name||!$email||!$address){$error='Please complete all fields.';}else{$done=true;$_SESSION['cart']=[];}}
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Checkout | NovaCart</title><link rel="stylesheet" href="css/style.css"></head><body><header class="site-header"><a class="logo" href="index.php">Nova<span>Cart</span></a><nav class="nav"><a href="index.php">Home</a><a href="products.php">Shop</a><a href="cart.php">Cart</a></nav></header><main class="auth-wrap"><?php if($done): ?><div class="auth-card success-card"><span class="success-icon">✓</span><h1>Order placed!</h1><p>This is a demo checkout. No payment was processed and no order was stored.</p><a class="btn full-btn" href="products.php">Continue shopping</a></div><?php else: ?><form class="auth-card" method="post"><p class="eyebrow">ALMOST YOURS</p><h1>Checkout</h1><p class="muted">Order total: <strong>₹<?= number_format($total,2) ?></strong></p><?php if($error): ?><div class="alert error"><?= htmlspecialchars($error) ?></div><?php endif; ?><label>Full name<input name="name" required maxlength="100" value="<?= htmlspecialchars($_POST['name']??($_SESSION['user']['name']??'')) ?>"></label><label>Email address<input type="email" name="email" required value="<?= htmlspecialchars($_POST['email']??($_SESSION['user']['email']??'')) ?>"></label><label>Delivery address<textarea name="address" required rows="3"><?= htmlspecialchars($_POST['address']??'') ?></textarea></label><button class="btn full-btn" type="submit">Place demo order</button><p class="muted">No real payment or delivery is arranged by this demo.</p></form><?php endif; ?></main><script src="js/script.js"></script></body></html>